import {packageExercises} from './packages.js';
import {addExamSheetExercises} from './exam-sheet.js';
import {courseEvidence} from './course-evidence.js';
export const topics = [
 {id:'vectors',name:'Vektorer & typer',icon:'[ ]',description:'Byg dit fundament med værdier, sekvenser og indeksering.'},
 {id:'frames',name:'Data frames',icon:'▦',description:'Lær dine data at kende. Udvælg rækker og kolonner.'},
 {id:'filter',name:'Filtrering & sortering',icon:'⇅',description:'Find de rigtige observationer med præcis logik.'},
 {id:'functions',name:'Funktioner & løkker',icon:'ƒ',description:'Gør kode genbrugelig, og tænk i vektorer.'},
 {id:'stats',name:'Statistik & NA',icon:'σ',description:'Rens data, opsummér og sammenlign grupper.'},
 {id:'simulation',name:'Simulation & modeller',icon:'⌁',description:'Fra terningekast til regression og kvartalsdata.'}
];
const sources={intro:'DALE26W35/Torsdag.R',list:'DALEW36/Pair Programming - Mandag.R',exam:'Eksamensøvning/Eksamenstræningsopgaver - Forsøg 1.R',clean:'DALEW36/Onsdag.R',loops:'Uge37/PairProgrammering10/PairProgramming1009.R',dice:'Terning/dice.R',model:'Mikroindikator/Mikroindikator.R',macro:'Mikroindikator/Mikroindikator.R'};
const car='biler <- mtcars';
export const exercises=[];
function add(id,topic,title,prompt,solution,{setup='',hint='',explanation='',level=1,source='exam',starter='# Skriv din løsning her\n',check=null,kind='code',options=null,answer=null,orderMatters=true}={}){exercises.push({id,topic,title,prompt,solution,setup,hint,explanation:explanation||hint,level,source:sources[source],starter,check,kind,options,answer,orderMatters});}
add('v-seq','vectors','En vektor med alder','Opret en vektor med navnet alder. Den skal indeholde alle hele tal fra og med 15 til og med 50 i stigende rækkefølge.','alder <- seq(15, 50)',{source:'intro',hint:'seq(fra, til) eller operatoren : laver en sekvens.',check:'isTRUE(all.equal(alder, 15:50))'});
add('v-income','vectors','Indkomst i faste trin','Opret en vektor med navnet indkomst med præcis 36 værdier. Første værdi skal være 10000, og hver ny værdi skal være 5000 større end den forrige. Lad R beregne værdierne.','indkomst <- seq(10000, by = 5000, length.out = 36)',{source:'intro',hint:'Brug seq(from = start, by = trin, length.out = antal). R beregner selv slutværdien.',check:'isTRUE(all.equal(indkomst, seq(10000, by = 5000, length.out = 36)))'});
add('v-types','vectors','Hvilken datatype?','Hvad returnerer typeof(x)?','"character"',{source:'list',kind:'choice',setup:'x <- c(2L, "5", TRUE)',options:['integer','double','character','logical'],answer:2,hint:'En vektor har én fælles datatype.',explanation:'Tekst får de øvrige værdier til at blive konverteret til character.'});
add('v-index','vectors','Hver anden værdi','Hent værdierne på plads 1, 3 og 5 i vektoren x. Skriv R-kode, der returnerer disse tre værdier; du skal ikke skrive værdierne manuelt.','x[c(1, 3, 5)]',{source:'list',setup:'x <- c(4, 9, 2, 15, 7, 12)',hint:'Indeks angiver positioner, ikke værdier.'});
add('v-logic','vectors','Læs en logisk vektor','Hvilke værdier er tilbage, når koden vælger værdier fra x, som er større end 7? Skriv selve værdierne med mellemrum imellem. Rækkefølgen i dit svar er ligegyldig.','9 15 12',{source:'list',kind:'output',setup:'x <- c(4, 9, 2, 15, 7, 12)\nx[x > 7]',hint:'Kun positioner med TRUE bliver udvalgt.',answer:'9 15 12',orderMatters:false});
add('v-matrix','vectors','Byg en matrix','Opret en matrix med navnet m med 3 rækker og 2 kolonner. Brug tallene 1 til 6. Fyld først hele den første kolonne oppefra og ned og derefter den anden kolonne.','m <- matrix(1:6, nrow = 3)',{source:'list',hint:'matrix() fylder som standard kolonnevis.',check:'isTRUE(all.equal(m, matrix(1:6, nrow=3)))'});
add('v-list','vectors','Ind i en liste','Hent værdien alder, som ligger i person inde i listen profil. Returnér selve alderen som et tal.','profil$person$alder',{source:'list',setup:'profil <- list(person = list(navn = "Kim", alder = 24), interesser = c("R", "data"))',hint:'Brug $ eller [[ ]] for at hente et element fra en liste.'});
add('v-brackets','vectors','Ét eller to sæt parenteser?','Hvad er længden af ml[1]?','1',{source:'list',kind:'choice',setup:'ml <- list(1:3, 1:6, 1:7)\nlength(ml[1])',options:['1','3','6','16'],answer:0,hint:'[ ] bevarer listen; [[ ]] henter indholdet.',explanation:'ml[1] er en liste med ét element. length(ml[[1]]) ville være 3.'});
add('d-head','frames','Mød dit datasæt','Returnér de første 6 rækker af biler.','head(biler, 6)',{setup:car,hint:'head() viser som standard de første seks rækker.'});
add('d-dim','frames','Rækker og kolonner','Returnér en vektor med antal rækker og antal kolonner i denne rækkefølge.','dim(biler)',{setup:car,hint:'dim() returnerer begge dimensioner.'});
add('d-column','frames','Hent en kolonne','Hent kolonnen mpg fra datasættet biler. Returnér kolonnens tal som en vektor, ikke som et data frame.','biler$mpg',{setup:car,hint:'$ henter en navngiven kolonne.'});
add('d-select','frames','To kolonner, alle biler','Returnér et data frame med mpg og hp i den rækkefølge.','biler[, c("mpg", "hp")]',{setup:car,hint:'Formatet er data[rækker, kolonner]. Et tomt felt før komma vælger alle rækker.'});
add('d-last','frames','Den sidste observation','Returnér den sidste række som et data frame.','biler[nrow(biler), ]',{setup:car,hint:'nrow(biler) giver rækkenummeret på den sidste observation.'});
add('d-kw','frames','Fra hestekræfter til kW','Opret en ny kolonne med navnet hp_kw i datasættet biler. Brug formlen: hp_kw = hp * 0.7457, hvor hp er bilens hestekræfter i kolonnen hp. Beregn værdien for hver række med R.','biler$hp_kw <- biler$hp * 0.7457',{setup:car,hint:'Brug biler$hp til at hente hestekræfterne. Gang dem med 0.7457, og gem resultatet i biler$hp_kw med <- eller =.',check:'isTRUE(all.equal(biler$hp_kw, mtcars$hp * 0.7457))'});
add('d-weight','frames','Fra pund til kilogram','Opret en ny kolonne med navnet weight_kg i datasættet biler. Kolonnen wt angiver vægt i 1000 pund. Brug formlen: weight_kg = wt * 1000 * 0.453592. Faktoren 1000 omregner til pund, og 0.453592 omregner pund til kg.','biler$weight_kg <- biler$wt * 1000 * 0.453592',{setup:car,hint:'Hent vægtene med biler$wt. Gang med både 1000 og 0.453592, og gem resultatet i biler$weight_kg. Lad R udføre gangestykkerne.',check:'isTRUE(all.equal(biler$weight_kg, mtcars$wt * 1000 * 0.453592))'});
add('d-drop','frames','Fravælg kolonner','Returnér biler uden disp og carb. Bevar rækkefølgen af de øvrige kolonner.','biler[, !names(biler) %in% c("disp", "carb")]',{setup:car,level:2,hint:'names(), %in% og ! kan bruges til at vælge de øvrige kolonner.'});
add('f-hp','filter','Find de stærke biler','Returnér alle rækker fra biler, hvor kolonnen hp er større end 150. Behold alle kolonner. Biler med præcis 150 hp skal ikke med.','biler[biler$hp > 150, ]',{setup:car,hint:'Mere end betyder >. Mindst betyder >=.'});
add('f-cyl','filter','Mindst seks cylindre','Returnér alle rækker fra biler, hvor cyl er 6 eller større. Behold alle kolonner.','biler[biler$cyl >= 6, ]',{setup:car,hint:'Brug >=, så 6 også kommer med.'});
add('f-and','filter','To krav på samme tid','Returnér rækker fra biler, hvor cyl er præcis 4, og mpg samtidig er større end 20. Begge krav skal være opfyldt i samme række. Behold alle kolonner.','biler[biler$cyl == 4 & biler$mpg > 20, ]',{setup:car,level:2,hint:'& kræver at begge betingelser er sande for hver række.'});
add('f-or','filter','Enten fire eller otte','Returnér rækker fra biler, hvor cyl er enten 4 eller 8. Behold alle kolonner.','biler[biler$cyl %in% c(4, 8), ]',{setup:car,level:2,hint:'Brug %in% eller to sammenligninger med |.'});
add('f-sort','filter','Sortér hele datasættet','Returnér biler sorteret efter mpg fra lavest til højest.','biler[order(biler$mpg), ]',{setup:car,level:2,hint:'order() giver rækkernes positioner. sort() på én kolonne flytter ikke resten af rækken.'});
add('f-top','filter','De fem mest økonomiske','Returnér de 5 biler med højest mpg, i faldende rækkefølge.','head(biler[order(biler$mpg, decreasing = TRUE), ], 5)',{setup:car,level:2,hint:'Kombinér order(..., decreasing = TRUE) og head(..., 5).'});
add('f-debug','filter','Ret fejlen: OG eller ELLER','Ret koden, så den returnerer biler med 6 cylindre OG over 100 hp.','biler[biler$cyl == 6 & biler$hp > 100, ]',{setup:car,kind:'debug',starter:'biler[biler$cyl == 6 | biler$hp > 100, ]',hint:'| inkluderer rækker, der kun opfylder ét af kravene.'});
add('f-empty','filter','Når ingen rækker matcher','Hvor mange rækker returneres?','0',{kind:'output',setup:'biler <- mtcars\nnrow(biler[biler$cyl == 5 & biler$mpg > 20, ])',answer:'0',hint:'mtcars har 4, 6 eller 8 cylindre.',explanation:'Ingen biler har 5 cylindre. Et tomt data frame er et korrekt resultat.'});
add('u-temp','functions','Celsius til Fahrenheit','Opret en funktion med navnet c_til_f og argumentet x. x er temperaturen i Celsius. Brug formlen: Fahrenheit = x * 9 / 5 + 32. Funktionen skal returnere de omregnede temperaturer og virke på både ét tal og en vektor.','c_til_f <- function(x) x * 9/5 + 32',{source:'intro',level:2,hint:'Regneoperatorer i R virker elementvist på vektorer.',check:'is.function(c_til_f) && isTRUE(all.equal(c_til_f(c(-40, 0, 10, 37, 100)), c(-40, 32, 50, 98.6, 212)))'});
add('u-inches','functions','En genbrugelig omregner','Opret en funktion med navnet tommer_til_cm og argumentet x. x er længden i tommer. Brug formlen: cm = x * 2.54. Funktionen skal returnere længden i cm og virke på både ét tal og en vektor.','tommer_til_cm <- function(x) x * 2.54',{source:'intro',hint:'En funktion kan returnere sit sidste udtryk uden return().',check:'is.function(tommer_til_cm) && isTRUE(all.equal(tommer_til_cm(c(0,1,5,10)), c(0,2.54,12.7,25.4)))'});
add('u-loop','functions','Summer med en løkke','Opret et objekt med navnet total, som indeholder summen af alle tal i vektoren priser. Brug en for-løkke til at lægge priserne sammen én ad gangen.','total <- 0\nfor (pris in priser) {\n  total <- total + pris\n}',{source:'loops',setup:'priser <- c(120, 250, 80, 190)',level:2,hint:'Start en akkumulator på 0, og læg hver pris til.',check:'isTRUE(all.equal(total, sum(priser))) && any(all.names(.user_expr) == "for")'});
add('u-vector','functions','Tænk i hele vektorer','Beregn gennemsnittet af vektoren priser. Træk dette gennemsnit fra hver pris. Returnér alle forskellene som en vektor i samme rækkefølge som priser.','priser - mean(priser)',{source:'loops',setup:'priser <- c(120, 250, 80, 190)',hint:'Én beregning kan udføres på alle værdier samtidig.'});
add('u-ifelse','functions','Kategorisér alder','Lav én tekstværdi for hver værdi i vektoren alder: "voksen", hvis alderen er 18 eller derover, og "barn", hvis den er under 18. Returnér tekstværdierne i samme rækkefølge som alder.','ifelse(alder >= 18, "voksen", "barn")',{source:'list',setup:'alder <- c(12, 18, 17, 45, 21)',level:2,hint:'ifelse(betingelse, hvis_sand, hvis_falsk) arbejder på en vektor.'});
add('u-apply','functions','Gennemsnit af hver liste','Beregn ét gennemsnit for hver del af listen loeb: ét for DHL og ét for park. Returnér de to tal som en vektor med navnene DHL og park, ikke som en liste.','sapply(loeb, mean)',{source:'list',setup:'loeb <- list(DHL = c(18, 20, 22), park = c(12, 16, 20))',level:2,hint:'sapply() anvender en funktion på hvert element og forsøger at forenkle resultatet.'});
add('s-mean','stats','Gennemsnitlig brændstoføkonomi','Returnér gennemsnittet af mpg.','mean(biler$mpg)',{setup:car,hint:'Brug mean() på den relevante kolonne.'});
add('s-na','stats','Gennemsnit med huller','Returnér gennemsnittet af x, uden at manglende værdier påvirker resultatet.','mean(x, na.rm = TRUE)',{setup:'x <- c(7, 4, NA, 10, 12)',source:'clean',hint:'Argumentet na.rm = TRUE fjerner NA fra beregningen.'});
add('s-count','stats','Hvor mange værdier mangler?','Returnér antallet af NA i x.','sum(is.na(x))',{setup:'x <- c(7, NA, 4, NA, 10)',source:'clean',hint:'TRUE tæller som 1, når du summerer en logisk vektor.'});
add('s-clean','stats','Rens bilernes data','Returnér kun de rækker, hvor mpg ikke mangler.','biler[!is.na(biler$mpg), ]',{setup:'biler <- data.frame(mpg = c(20, NA, 25, 18, NA), pris = c(80, 90, 120, 70, 95))',source:'clean',level:2,hint:'!is.na(...) er TRUE for kendte værdier.'});
add('s-sd','stats','Mål spredningen','Returnér stikprøvens standardafvigelse for priser.','sd(priser)',{setup:'priser <- c(120, 250, 80, 190)',source:'loops',hint:'sd() bruger n − 1 i nævneren for variansen.'});
add('s-group','stats','Sammenlign cylindergrupper','Returnér et data frame med gennemsnitlig mpg for hver cyl-gruppe. Brug aggregate().','aggregate(mpg ~ cyl, data = biler, FUN = mean)',{setup:car,level:2,hint:'aggregate(værdi ~ gruppe, data = datasæt, FUN = mean).'});
add('s-table','stats','Tæl biler i hver gruppe','Tæl, hvor mange biler der har hver værdi i kolonnen cyl. Returnér en frekvenstabel med table(), så antallet af biler med 4, 6 og 8 cylindre fremgår.','table(biler$cyl)',{setup:car,hint:'table() tæller forekomsterne af hver værdi.'});
add('s-na-debug','stats','Ret fejlen: sammenligning med NA','Ret koden, så kun de kendte værdier returneres.','x[!is.na(x)]',{setup:'x <- c(3, NA, 7, 9)',source:'clean',kind:'debug',starter:'x[x != NA]',hint:'NA er ukendt. Brug is.na() til at teste for manglende værdier.'});
add('m-dice','simulation','Kast en terning 100 gange','Opret en vektor med navnet kast med 100 tilfældige terningekast. Hvert kast skal være et helt tal fra 1 til 6, og alle seks tal skal være lige sandsynlige. Brug sample(), og tillad at samme tal trækkes flere gange.','kast <- sample(1:6, 100, replace = TRUE)',{source:'dice',level:2,hint:'Med replace = TRUE kan samme side trækkes flere gange.',check:'is.numeric(kast) && length(kast) == 100 && all(kast %in% 1:6) && any(all.names(.user_expr) == "sample")'});
add('m-prob','simulation','Andelen af seksere','Beregn, hvor stor en andel af værdierne i vektoren kast der er 6. Brug formlen: andel = antal seksere / antal kast. Returnér ét tal mellem 0 og 1, ikke en procent.','mean(kast == 6)',{source:'dice',setup:'kast <- c(1, 6, 3, 6, 2, 4, 6, 5, 1, 2)',hint:'Gennemsnittet af en logisk vektor er andelen af TRUE.'});
add('m-replicate','simulation','Gentag en simulation','Opret en vektor med navnet summer. Simulér to seks-sidede terningekast, læg de to kast sammen, og gentag hele forsøget 200 gange med replicate(). Vektoren skal indeholde 200 summer. Samme terningetal må trækkes flere gange.','summer <- replicate(200, sum(sample(1:6, 2, replace = TRUE)))',{source:'dice',level:3,hint:'replicate(antal, udtryk) gentager en beregning.',check:'is.numeric(summer) && length(summer) == 200 && all(summer >= 2 & summer <= 12 & summer == floor(summer)) && all(c("replicate", "sample") %in% all.names(.user_expr))'});
add('m-seed','simulation','Hvorfor sætte et seed?','Hvad er formålet med set.seed(42) før sample()?','Gøre tilfældige resultater reproducerbare',{source:'dice',kind:'choice',options:['Sikre præcis lige mange af hver værdi','Gøre tilfældige resultater reproducerbare','Sortere resultaterne','Fjerne tilfældigheden fra modellen'],answer:1,hint:'Det styrer starttilstanden for tilfældighedsgeneratoren.'});
add('m-quarter','simulation','Fra måneder til kvartaler','Vektoren maaned indeholder månedsnumrene 1 til 12. Returnér kvartalsnummeret for hver måned: januar–marts er 1, april–juni er 2, juli–september er 3 og oktober–december er 4. Bevar månedernes rækkefølge.','ceiling(maaned / 3)',{source:'macro',setup:'maaned <- 1:12',level:2,hint:'Divider måneden med 3, og rund op med ceiling().'});
add('m-growth','simulation','Årlig vækst','Beregn væksten i procent fra foer til nu for hvert par af værdier. Brug formlen: vækst i procent = (nu / foer - 1) * 100. Returnér én vækstrate pr. par i samme rækkefølge som vektorerne.','(nu / foer - 1) * 100',{source:'macro',setup:'foer <- c(100, 200, 80)\nnu <- c(105, 190, 88)',level:2,hint:'Procentvis vækst er (ny / gammel − 1) × 100.'});
add('m-lm','simulation','Din første regressionsmodel','Opret en lineær regressionsmodel med navnet model ud fra datasættet biler. Modellen skal forklare mpg ud fra wt: mpg er y (det, der forklares), og wt er x (den forklarende variabel). Brug lm().','model <- lm(mpg ~ wt, data = biler)',{setup:car,source:'model',level:3,hint:'lm(y ~ x, data = ...) tilpasser en lineær model.',check:'inherits(model, "lm") && isTRUE(all.equal(coef(model), coef(lm(mpg ~ wt, data=mtcars))))'});
add('m-r2','simulation','Forklaringsgrad','Hent R², også kaldet forklaringsgraden, fra den allerede oprettede model. Returnér selve tallet mellem 0 og 1, ikke en procent eller hele modeloversigten.','summary(model)$r.squared',{setup:'model <- lm(mpg ~ wt, data = mtcars)',source:'model',level:3,hint:'summary(model) indeholder r.squared.'});
add('m-merge','simulation','Saml data på kvartal','Saml datasættene forbrug og tillid ved at matche værdierne i deres kolonne kvartal. Returnér ét datasæt med kolonnerne kvartal, forbrug og tillid. Medtag kun kvartaler, der findes i begge datasæt.','merge(forbrug, tillid, by = "kvartal")',{source:'macro',level:3,setup:'forbrug <- data.frame(kvartal = c("2024K1", "2024K2", "2024K3"), forbrug = c(100, 104, 106))\ntillid <- data.frame(kvartal = c("2024K1", "2024K2"), tillid = c(-5, -2))',hint:'Brug merge(forbrug, tillid, by = "kvartal"). by angiver den kolonne, som rækkerne skal matches på. Som standard beholdes kun kvartaler, der findes i begge datasæt.'});

addExamSheetExercises(add);
exercises.push(...packageExercises);

// Answer contracts are shared by practice, exams and generated variants.
export function answerPolicy(ex) {
 const rowOrdered=new Set(['d-head','d-last','d-first-five','d-new-ten']);
 const columnOrdered=new Set(['d-select','d-four-columns','d-drop','pkg-select']);
 const sorting={ 'f-sort':['mpg',false], 'f-top':['mpg',true], 'f-hp-desc':['hp',true], 'pkg-arrange':['hp',true] };
 return {rowOrderMatters:rowOrdered.has(ex.id),columnOrderMatters:columnOrdered.has(ex.id),
   valueOrderMatters:ex.id!=='v-index',sortBy:sorting[ex.id]?.[0]||null,descending:sorting[ex.id]?.[1]||false};
}
for (const ex of exercises) {
 ex.comparison=answerPolicy(ex);
 ex.evidence=courseEvidence[ex.id]||{};
 const paths=[...new Set(Object.values(ex.evidence).flat())];
 if(paths.length)ex.source=paths.join(' · ');
}

export function makeVariant(seed=Date.now()) {
 const n=Math.abs(Number(seed))%100000; const threshold=100+(n%12)*10;
 const templates=[
  {topic:'filter',title:'Nye data · filtrér hestekræfter',setup:car,prompt:`Returnér alle rækker fra biler, hvor hp er større end ${threshold}. Behold alle kolonner. Rækker med præcis ${threshold} hp skal ikke med.`,solution:`biler[biler$hp > ${threshold}, ]`,hint:'Brug logisk indeksering og operatoren >.',level:2},
  {topic:'vectors',title:'Nye data · en sekvens',setup:'',prompt:`Opret en vektor med navnet x med præcis 8 værdier. Start ved ${n%20+3}, og læg ${n%5+2} til for hver ny værdi. Lad R beregne værdierne.`,solution:`x <- seq(${n%20+3}, by = ${n%5+2}, length.out = 8)`,check:`isTRUE(all.equal(x, seq(${n%20+3}, by=${n%5+2}, length.out=8)))`,hint:'Brug by til trinstørrelsen og length.out til antallet af værdier.',level:1},
  {topic:'stats',title:'Nye data · håndtér NA',setup:`x <- c(${n%13+2}, NA, ${n%17+4}, ${n%9+3}, NA)`,prompt:'Returnér gennemsnittet af de kendte værdier.',solution:'mean(x, na.rm = TRUE)',hint:'Husk na.rm = TRUE.',level:1},
  {topic:'functions',title:'Nye data · en omregner',setup:'',prompt:`Opret funktionen omregn med argumentet x. Brug formlen: resultat = x * ${n%8+2} + ${n%11+1}. Returnér resultatet. Funktionen skal virke på både ét tal og en vektor.`,solution:`omregn <- function(x) x * ${n%8+2} + ${n%11+1}`,check:`is.function(omregn) && isTRUE(all.equal(omregn(c(-2,0,1,5)), c(-2,0,1,5) * ${n%8+2} + ${n%11+1}))`,hint:'En funktion kan arbejde direkte på en hel vektor.',level:2}
 ];
 const variant={id:`variant-${n}`,source:'Genereret variant af dit undervisningsmateriale',kind:'code',starter:'# Skriv din løsning her\n',explanation:'Denne variant træner samme princip med nye værdier.',...templates[n%templates.length]};
 return {...variant,comparison:answerPolicy(variant)};
}
export const kindLabels={code:'Skriv kode',debug:'Ret fejlen',choice:'Vælg svar',output:'Forudsig output'};
